mapper.select:
SELECT GROUP_SEQ AS groupSeq, GROUP_NAME AS groupName, GROUP_COLOR AS groupColor FROM UI_ADMIN_USER_GROUP WHERE USE_YN = 'Y' AND ADMIN_ID = #{adminId}
AND GROUP_NAME LIKE CONCAT('%', #{searchStr}, '%')
ORDER BY GROUP_NAME

SELECT	COUNT(*) AS CNT
FROM	UI_ADMIN_USER_GROUP
WHERE	ADMIN_ID = #{adminId}
AND		GROUP_NAME = #{groupName}

mapper.update:
UPDATE	UI_ADMIN_USER_GROUP
SET		GROUP_NAME = #{groupName},
		GROUP_COLOR = #{groupColor}
WHERE	GROUP_SEQ = #{groupSeq}

