SELECT	COUNT(*) AS CNT
FROM	UI_ADMIN_USER_GROUP_LIST 
WHERE	GROUP_SEQ = #{groupSeq}

AND		USER_ID = #{userId}

SELECT	COUNT(*) AS CNT
FROM	UI_USERS 
WHERE	USER_ID = #{userId}

mapper.delete:
DELETE	
FROM	UI_ADMIN_USER_GROUP_LIST
WHERE	GROUP_SEQ = #{groupSeq}

AND		USER_ID = #{userId}

mapper.select:
SELECT DISTINCT B.GROUP_SEQ AS groupSeq, B.GROUP_NAME AS groupName FROM UI_ADMIN_USER_GROUP_LIST A LEFT JOIN UI_ADMIN_USER_GROUP B ON A.GROUP_SEQ = B.GROUP_SEQ WHERE USE_YN = 'Y' AND ADMIN_ID = #{adminId}
AND FIND_IN_SET (A.USER_ID, #{itemList})
ORDER BY B.GROUP_NAME
